const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var geom = ee.Geometry.Polygon([
    [151, -29.5],
    [152.5, -29.5],
    [152.5, -31.5],
    [151, -31.5]
  ]);
  var date = '2025-08-02';

  // Helper function to check collection size
  function checkCollection(collection) {
    var size = collection.size().getInfo();
    return size;
  }

  // 2. Data Acquisition - Try Sentinel-2 first
  var s2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date, '2025-08-03')
    .filterBounds(geom)
    .select('SCL');

  var s2Count = checkCollection(s2);
  print('Sentinel-2 Images:', s2Count);

  var img;
  var collectionType = 'none';

  if (s2Count > 0) {
    img = s2.first();
    collectionType = 's2';
  } else {
    // Try MODIS snow cover as fallback
    var modis = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date, '2025-08-03')
      .filterBounds(geom)
      .select('NDSI_Snow_Cover');

    var modisCount = checkCollection(modis);
    print('MODIS Images:', modisCount);

    if (modisCount > 0) {
      img = modis.first();
      collectionType = 'modis';
    } else {
      print('No images found for date/location.');
      print('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Count valid pixels
  var count;
  var snowCount;
  var cloudCount;

  if (collectionType === 's2') {
    // SCL band: snow = 11, clouds = 8,9,10
    var scl = img.select('SCL');
    snowCount = scl.eq(11)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('SCL').getInfo();

    cloudCount = scl.eq(8).or(scl.eq(9)).or(scl.eq(10))
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('SCL').getInfo();

    // Total valid pixels (excluding nodata, saturated, etc.)
    count = scl.gt(0).and(scl.lt(12))
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('SCL').getInfo();
  } else { // MODIS
    var ndsi = img.select('NDSI_Snow_Cover');
    // MODIS values: 1-100 = snow, 250 = cloud
    snowCount = ndsi.gte(1).and(ndsi.lte(100))
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('NDSI_Snow_Cover').getInfo();

    cloudCount = ndsi.eq(250)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('NDSI_Snow_Cover').getInfo();

    // Total valid pixels (excluding fill 255)
    count = ndsi.neq(255)
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('NDSI_Snow_Cover').getInfo();
  }

  print('Valid pixels:', count);
  print('Snow pixels:', snowCount);
  print('Cloud pixels:', cloudCount);

  // 4. Check for no valid pixels
  if (count === 0 || count === null) {
    print('No valid pixels after processing.');
    print('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  if (snowCount === null || cloudCount === null) {
    print('<answer>C3</answer>');
  } else if (snowCount > 0 && cloudCount === 0) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
